<script setup lang="ts">
import {computed,h,onMounted,onUnmounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';
import type {ColumnDef} from '@tanstack/vue-table';
import {api,type KnowledgeVersion} from '../api';import {useAuth} from '../composables/auth';
import PageHeader from '../components/PageHeader.vue';import DataTable from '../components/DataTable.vue';import CatalogPagination from '../components/CatalogPagination.vue';
import Button from '../components/ui/Button.vue';import Input from '../components/ui/Input.vue';import Select from '../components/ui/Select.vue';
const {canOperate}=useAuth(),route=useRoute();
const rows=ref<KnowledgeVersion[]>([]),query=ref(''),archived=ref('false'),page=ref(1),total=ref<number>(),loading=ref(false),error=ref('');
const current=ref<KnowledgeVersion|null>(null),versions=ref<KnowledgeVersion[]>([]),historyPage=ref(1),historyTotal=ref<number>(),detailLoading=ref(false),detailError=ref('');
const editing=ref(false),title=ref(''),content=ref(''),saving=ref(false),notice=ref(''),fileInput=ref<HTMLInputElement|null>(null);
const bytes=computed(()=>new TextEncoder().encode(content.value).length);
const dirty=computed(()=>editing.value&&(title.value!==(current.value?.title??'')||content.value!==(current.value?.content??'')));
let generation=0,detailGeneration=0,timer:ReturnType<typeof setTimeout>|undefined;
async function load(p=page.value){const gen=++generation;loading.value=true;error.value='';try{const v=await api.knowledge({page:p,q:query.value,archived:archived.value==='true'});if(gen!==generation)return;rows.value=v.items;page.value=v.page;total.value=v.total;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
async function history(p=1){if(!current.value)return;const gen=detailGeneration;try{const v=await api.knowledge({documentId:current.value.documentId,page:p});if(gen!==detailGeneration)return;versions.value=v.items;historyPage.value=v.page;historyTotal.value=v.total;}catch(e){if(gen===detailGeneration)detailError.value='版本历史读取失败：'+(e as Error).message;}}
async function inspect(v:KnowledgeVersion|{id:number}){if(saving.value)return;if(dirty.value){notice.value='有未保存的修改，请先保存或放弃。';return;}const gen=++detailGeneration;detailLoading.value=true;detailError.value='';editing.value=false;try{const result=await api.knowledgeVersion(v.id);if(gen!==detailGeneration)return;current.value=result;title.value=result.title;content.value=result.content??'';await history();}catch(e){if(gen===detailGeneration)detailError.value='文档正文读取失败：'+(e as Error).message;}finally{if(gen===detailGeneration)detailLoading.value=false;}}
function create(){if(saving.value)return;if(dirty.value){notice.value='有未保存的修改，请先保存或放弃。';return;}detailGeneration++;detailLoading.value=false;current.value=null;versions.value=[];editing.value=true;title.value='';content.value='';detailError.value='';notice.value='';}
function edit(){if(saving.value)return;editing.value=true;notice.value='';}
function discard(){editing.value=false;title.value=current.value?.title??'';content.value=current.value?.content??'';notice.value='';detailError.value='';}
async function save(){if(!canOperate.value||saving.value)return;saving.value=true;detailError.value='';try{const v=await api.saveKnowledge({title:title.value,content:content.value,baseVersion:current.value?.latestVersion??current.value?.version??0},current.value?.documentId);editing.value=false;current.value=v;notice.value='已保存不可变版本 v'+v.version;await history();await load();}catch(e){detailError.value=(e as Error).message;}finally{saving.value=false;}}
async function archive(){if(!current.value||saving.value)return;saving.value=true;detailError.value='';try{await api.archiveKnowledge(current.value.documentId,!current.value.archived);current.value={...current.value,archived:!current.value.archived};notice.value=current.value.archived?'已归档；历史版本和已有任务引用继续保留。':'已恢复，可供新扫描选择。';await load();}catch(e){detailError.value=(e as Error).message;}finally{saving.value=false;}}
async function upload(event:Event){const el=event.target as HTMLInputElement,file=el.files?.[0];el.value='';if(!file)return;try{if(!/\.(md|txt)$/i.test(file.name)||file.size>65536)throw new Error('请选择不超过 64 KiB 的 .md 或 .txt 文件。');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(!text.trim()||text.includes('\0'))throw new Error('知识文档必须是非空 UTF-8 文本。');content.value=text;if(!title.value)title.value=file.name;}catch(e){detailError.value=(e as Error).message;}}
const columns:ColumnDef<KnowledgeVersion>[]=[{accessorKey:'title',header:'知识文档',size:240,enableSorting:false,cell:c=>h('button',{class:'document-title',onClick:(e:Event)=>{e.stopPropagation();void inspect(c.row.original);}},c.getValue<string>())},{accessorKey:'version',header:'当前版本',size:80,enableSorting:false,cell:c=>'v'+c.getValue()},{accessorKey:'sha256',header:'SHA-256',size:160,enableSorting:false,cell:c=>h('code',c.getValue<string>().slice(0,16))}];
watch([query,archived],()=>{generation++;clearTimeout(timer);timer=setTimeout(()=>void load(1),250);});watch(()=>route.query.version,value=>{const id=Number(value);if(Number.isSafeInteger(id)&&id>0)void inspect({id});},{immediate:true});onMounted(()=>void load());onUnmounted(()=>{generation++;detailGeneration++;clearTimeout(timer);});
</script>
<template><div class="knowledge-workspace">
 <PageHeader title="知识文档" description="为安全审计保存可追溯的参考资料。每次修改生成新版本，已创建任务使用原来的正文和哈希。"><Button v-if="canOperate" @click="create">新建知识文档</Button></PageHeader>
 <p v-if="notice" class="notice" role="status">{{notice}}</p>
 <div class="knowledge-layout"><section aria-label="知识文档列表" class="document-list"><div class="list-tools"><Input v-model="query" aria-label="搜索知识文档标题" placeholder="搜索文档标题"/><Select v-model="archived" aria-label="文档归档状态" :options="[{value:'false',label:'可用文档'},{value:'true',label:'已归档'}]"/></div>
 <p v-if="error" class="error" role="alert">列表读取失败：{{error}} <Button variant="outline" size="sm" @click="load()">重试</Button></p>
 <DataTable :data="rows" :columns="columns" :row-key="v=>String(v.id)" :row-click="inspect" :loading="loading" :unavailable="Boolean(error)" empty-title="暂无知识文档" empty-hint="创建文档或上传 UTF-8 文本，供扫描引用。"/>
 <CatalogPagination label="知识文档列表" :page="page" :page-size="50" :total="total" :loading="loading" :unavailable="Boolean(error)" @change="load"/>
 </section>
 <aside v-if="current||editing||detailLoading||detailError" class="document-inspector" aria-label="知识文档详情">
 <h2>{{editing?(current?'保存新版本':'新建知识文档'):(current?.title??'知识文档')}}</h2>
 <p v-if="detailLoading" role="status">正在读取文档正文…</p><p v-if="detailError" class="error" role="alert">{{detailError}} <Button v-if="current&&!editing" variant="outline" size="sm" @click="inspect(current)">重试读取</Button></p>
 <form v-if="editing" @submit.prevent="save"><label for="knowledge-title">文档标题</label><Input id="knowledge-title" v-model="title" maxlength="128" required/><div class="editor-tools"><label for="knowledge-content">文档正文</label><Button variant="outline" size="sm" type="button" @click="fileInput?.click()">上传文本</Button><input ref="fileInput" type="file" accept=".md,.txt" hidden @change="upload"/></div><textarea id="knowledge-content" v-model="content" rows="15" required aria-describedby="knowledge-limit"></textarea><p id="knowledge-limit">{{bytes}} / 65536 字节 · UTF-8 Markdown 或纯文本</p><p v-if="current">以最新版本 v{{current.latestVersion??current.version}} 为基准保存，正文来自 v{{current.version}}；版本冲突时保留当前输入。</p><div class="inspector-actions"><Button type="submit" :loading="saving" :disabled="!title.trim()||!content.trim()||bytes>65536">保存文档版本</Button><Button type="button" variant="ghost" :disabled="saving" @click="discard">放弃修改</Button></div></form>
 <template v-else-if="current&&!detailLoading"><dl><dt>版本</dt><dd>v{{current.version}} · 记录 #{{current.id}}</dd><dt>状态</dt><dd>{{current.archived?'已归档':'可用'}}</dd><dt>SHA-256</dt><dd><code>{{current.sha256}}</code></dd><dt>保存时间</dt><dd>{{current.createdAt}}</dd></dl><div v-if="canOperate" class="inspector-actions"><Button v-if="!current.archived" variant="outline" size="sm" @click="edit">编辑为新版本</Button><Button variant="ghost" size="sm" :loading="saving" @click="archive">{{current.archived?'恢复文档':'归档文档'}}</Button></div><h3>原始正文</h3><pre class="document-content">{{current.content}}</pre><h3>版本历史</h3><ul class="versions"><li v-for="v in versions" :key="v.id"><button :aria-current="v.id===current.id?'true':undefined" @click="inspect(v)">v{{v.version}} · {{v.title}} · {{v.createdAt}}</button></li></ul><CatalogPagination label="文档版本历史" :page="historyPage" :page-size="50" :total="historyTotal" @change="history"/></template>
 </aside></div>
</div></template>
<style scoped>
.knowledge-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(var(--inspector-width-sm),var(--inspector-width-lg));gap:var(--space-5);align-items:start}.knowledge-layout:has(>section:last-child){grid-template-columns:1fr}.document-list{min-width:0}.list-tools{display:flex;gap:var(--space-2);margin-bottom:var(--space-3)}.list-tools>input{flex:1}.document-inspector{border-left:1px solid var(--border-default);padding-left:var(--space-4);min-width:0}h2{font-size:var(--font-size-lg);font-weight:var(--font-weight-semibold);margin:0 0 var(--space-3);overflow-wrap:anywhere}h3{font-size:var(--font-size-sm);margin:var(--space-4) 0 var(--space-2)}label{display:block;font-size:var(--font-size-sm);margin:var(--space-2) 0 var(--space-1)}p{font-size:var(--font-size-xs);color:var(--text-secondary);line-height:var(--line-height-body)}.notice{margin-bottom:var(--space-3)}.error{color:var(--state-danger)}.editor-tools,.inspector-actions{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap;margin-top:var(--space-3)}.editor-tools{justify-content:space-between}.editor-tools label{margin:0}textarea{width:100%;resize:vertical;min-height:calc(var(--height-table-row)*6);border:1px solid var(--border-control);border-radius:var(--radius-sm);padding:var(--space-2);background:var(--surface-primary);color:var(--text-primary);font:var(--font-size-sm)/var(--line-height-body) var(--font-mono)}dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:var(--space-2) var(--space-3);font-size:var(--font-size-xs)}dt{color:var(--text-tertiary)}dd{margin:0;overflow-wrap:anywhere}code{font-family:var(--font-mono);font-size:var(--font-size-xs)}.document-content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:calc(var(--height-table-row)*12);overflow:auto;font:var(--font-size-sm)/var(--line-height-body) var(--font-mono);padding:var(--space-3);background:var(--surface-secondary);border:1px solid var(--border-subtle)}.versions{list-style:none;margin:0;padding:0}.versions button{font-size:var(--font-size-xs);text-align:left;overflow-wrap:anywhere;color:var(--text-secondary);padding:var(--space-2) 0;width:100%;border-top:1px solid var(--border-subtle)}.versions button[aria-current=true]{color:var(--accent-primary)}:deep(.document-title){font-weight:var(--font-weight-medium);color:var(--text-primary);text-align:left;overflow-wrap:anywhere}@media(max-width:1000px){.knowledge-layout{grid-template-columns:1fr}.document-inspector{border-left:0;border-top:1px solid var(--border-default);padding:var(--space-4) 0 0}.list-tools{flex-wrap:wrap}}
</style>
